import {DIGITAL_MODULES} from './digital-hardware.js';
import {CATALOG} from './core.js';
export function digitalDisplay(c){const d=CATALOG[c.type],m=DIGITAL_MODULES[c.type],s=d.scale;if(!m)return '';
 if(c.type==='keypad4x4')return m.keys.map((k,i)=>`<rect data-matrix-key="${c.id}" data-key-index="${i}" x="${k.x*s}" y="${k.y*s}" width="${k.width*s}" height="${k.height*s}" rx="${3*s}" fill="${(c.params.keyMask??0)&(1<<i)?'#36d9b6':'transparent'}" fill-opacity=".4" role="button" tabindex="0" aria-pressed="${!!((c.params.keyMask??0)&(1<<i))}" aria-label="${c.id} tuş ${k.label}" style="cursor:pointer"/>`).join('');
 if(c.type==='ky040')return `<g transform="translate(${m.pivot.x*s} ${m.pivot.y*s}) rotate(${(c.params.position??0)*18})" pointer-events="none"><path d="M0 -16v8" stroke="#69f0cf" stroke-width="2"/></g>`+[-1,1].map((v,i)=>`<g data-encoder-step="${c.id}" data-step="${v}" role="button" tabindex="0" aria-label="${c.id} ${v>0?'saat yönünde':'ters yönde'} çevir" style="cursor:pointer"><rect x="${(5+i*35)*s}" y="${54*s}" width="${23*s}" height="${13*s}" rx="3" fill="#172d3b"/><text x="${(16+i*35)*s}" y="${65*s}" fill="#b8ece0" font-size="${13*s}" text-anchor="middle">${v>0?'+':'−'}</text></g>`).join('');
 if(c.type!=='tm1637')return '';const r=m.display,paths=['M5 0h16l3 3-3 3H5L2 3Z','M25 4v12l-3 3-3-3V7Z','M25 22v12l-6-3v-6l3-3Z','M5 34h16l3 3-3 3H5L2 37Z','M0 22l6 3v6l-6 3Z','M0 4l6 3v9l-3 3-3-3Z','M5 16h16l3 3-3 3H5L2 19Z'];
 const body=Array.from({length:4},(_,i)=>`<g transform="translate(${3+i*37} 1)">${paths.map((p,b)=>`<path data-tm-segment="${c.id}" data-digit="${i}" data-bit="${b}" d="${p}" fill="#351923"/>`).join('')}</g>`).join('')+`<g data-tm-colon="${c.id}" fill="#351923"><circle cx="73" cy="13" r="2"/><circle cx="73" cy="29" r="2"/></g>`;
 return `<svg x="${r.x*s}" y="${r.y*s}" width="${r.width*s}" height="${r.height*s}" viewBox="0 0 146 42" pointer-events="none" aria-label="${c.id} canlı 4 hane"><rect width="146" height="42" fill="#090c12"/>${body}</svg>`;
}
export function updateDigital(packet){const modules=packet.digitalDevices?.modules||{};for(const n of document.querySelectorAll('[data-tm-segment]')){const d=modules[n.dataset.tmSegment],on=d?.powered&&d.on&&((d.frame[+n.dataset.digit]||0)&(1<<Number(n.dataset.bit)));n.setAttribute('fill',on?'#ff4652':'#351923');n.setAttribute('opacity',on?.25+.75*d.duty:1);}for(const n of document.querySelectorAll('[data-tm-colon]')){const d=modules[n.dataset.tmColon];n.setAttribute('fill',d?.powered&&d.on&&(d.frame[1]&128)?'#ff4652':'#351923');}}
